'use strict';
// Presentation and interaction layer. Existing data and operational workflows are preserved.
const ui = { drawer: null, drawerFocus: null, quick: '', compact: readStorage('opd-compact',false), reduced: readStorage('opd-reduced-motion',null), lastPage: '', scroll: {}, savedFilters: readStorage('opd-filters',{}) };
for (const key of ['search','status','priority','dept','pageNumber']) if(ui.savedFilters[key]!==undefined) state[key]=ui.savedFilters[key];
ui.quick=ui.savedFilters.quick||'';
const systemMotion=matchMedia('(prefers-reduced-motion: reduce)');
const baseRender=render, baseBindPage=bindPage, baseFilteredPatients=filteredPatients, baseModal=modal, baseCloseModal=closeModal;
const commandActions=[['dashboard','Tổng quan vận hành','home'],['patients','Theo dõi bệnh nhân','users'],['ai','Gợi ý điều phối AI','spark'],['simulation','Simulation Studio','chart'],['wizard','SAS Wizard','wand'],['users','Người dùng & Phân quyền','shield'],['logs','Nhật ký hệ thống','file']];
function motionOff(){return ui.reduced===true||systemMotion.matches;}
function saveFilters(){let out={quick:ui.quick};for(const k of ['search','status','priority','dept','pageNumber'])out[k]=state[k];localStorage.setItem('opd-filters',JSON.stringify(out));}
function activeQueue(p){return p.status!=='Hoàn tất';}
function searchText(s){return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');}
function matchQuick(p){return !ui.quick||(ui.quick==='long'&&activeQueue(p)&&p.wait>30)||(ui.quick==='priority'&&activeQueue(p)&&p.priority==='Cao')||(ui.quick==='dispatch'&&activeQueue(p)&&(p.wait>40||p.priority==='Cao'));}
filteredPatients=function(){return state.patients.filter(p=>searchText(p.name+' '+p.id+' '+p.phone).includes(searchText(state.search))&&(state.status==='Tất cả'||p.status===state.status)&&(state.priority==='Tất cả'||p.priority===state.priority)&&(state.dept==='Tất cả'||p.department===state.dept)&&matchQuick(p));};
function uiHeader(title,sub,action=''){return `<div class="page-heading"><div><div class="page-kicker"><span class="dot"></span> ĐIỀU HÀNH NGOẠI TRÚ</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${action||`<span class="date-pill">${icon('calendar')} 14 tháng 10, 2026</span>${button('Xuất báo cáo','export-dashboard','','download')}`}</div></div>`;}
function roomPulse(){return `<div class="room-pulse">${[['Nội tổng quát','12 / 16 phòng',75,''],['Xét nghiệm','28 / 40 lượt',70,'green'],['Chẩn đoán hình ảnh','10 / 16 lượt',63,'purple'],['Nhà thuốc','18 / 24 lượt',75,'teal']].map(([n,s,v,c])=>`<div><div class="between"><span class="flex">${circle(c==='purple'?'monitor':c==='green'?'flask':'hospital',c)}<span><strong>${n}</strong><small>${s}</small></span></span><b>${v}%</b></div><div class="progress"><span style="width:${v}%;background:${c==='green'?'#12a77d':c==='purple'?'#8471e8':c==='teal'?'#0a9fa7':'#2785ee'}"></span></div></div>`).join('')}</div>`;}
dashboard=operationalDashboard;
donut=operationalDonut;
resourcesTable=operationalResources;
alerts=operationalAlerts;
patients=function(){let list=filteredPatients(),pages=Math.max(1,Math.ceil(list.length/10));state.pageNumber=Math.min(state.pageNumber,pages);const quicks=[['long','clock','Chờ trên 30 phút',p=>activeQueue(p)&&p.wait>30],['priority','flag','Ưu tiên cao',p=>activeQueue(p)&&p.priority==='Cao'],['dispatch','transfer','Cần điều phối',p=>activeQueue(p)&&(p.wait>40||p.priority==='Cao')]];return uiHeader('Theo dõi bệnh nhân','Tra cứu hồ sơ, theo dõi tiến trình và điều phối phòng khám.',button('Đăng ký bệnh nhân','new-patient','primary','plus'))+`<div class="patient-summary"><div class="patient-total">${circle('users')}<span><strong>${state.patients.length}</strong><small>hồ sơ đã tiếp nhận</small></span></div>${quicks.map(([id,i,t,test])=>`<button class="queue-summary ${ui.quick===id?'selected':''}" data-quick="${id}" aria-pressed="${ui.quick===id}">${circle(i,id==='priority'?'red':id==='dispatch'?'purple':'amber')}<span><strong>${state.patients.filter(test).length}</strong><small>${t}</small></span>${icon('chevron')}</button>`).join('')}</div><section class="card patient-workspace"><div class="patient-workspace-head"><div class="status-tabs" role="group" aria-label="Lọc trạng thái">${['Tất cả','Đang chờ','Đang khám','Đang làm CLS','Hoàn tất'].map(x=>`<button data-status="${x}" class="${state.status===x?'active':''}" aria-pressed="${state.status===x}">${x}<span>${x==='Tất cả'?state.patients.length:state.patients.filter(p=>p.status===x).length}</span></button>`).join('')}</div><div class="patient-controls"><div class="search">${icon('search')}<input id="patient-search" value="${esc(state.search)}" placeholder="Tìm tên, mã hồ sơ, số điện thoại..." aria-label="Tìm bệnh nhân"><kbd>/</kbd></div><select id="patient-dept" aria-label="Phòng chức năng">${['Tất cả',...new Set(state.patients.map(p=>p.department))].map(x=>`<option value="${esc(x)}" ${x===state.dept?'selected':''}>${x==='Tất cả'?'Tất cả phòng khám':esc(x)}</option>`).join('')}</select><select id="patient-priority" aria-label="Mức ưu tiên">${['Tất cả','Cao','Bình thường','Thấp'].map(x=>`<option value="${x}" ${x===state.priority?'selected':''}>${x==='Tất cả'?'Mức ưu tiên':x}</option>`).join('')}</select><button class="btn icon-only ${ui.compact?'soft':''}" data-ui="density" aria-label="${ui.compact?'Chuyển sang bảng thoáng':'Chuyển sang bảng gọn'}" title="Mật độ bảng" aria-pressed="${ui.compact}">${icon('menu')}</button>${button('Xuất CSV','export-patients','','download')}</div>${ui.quick||state.search||state.status!=='Tất cả'||state.dept!=='Tất cả'||state.priority!=='Tất cả'?`<div class="active-filter-bar"><span>${icon('filter')} ${list.length} hồ sơ phù hợp ${ui.quick?'· '+quicks.find(x=>x[0]===ui.quick)[2]:''}</span>${button('Xóa bộ lọc','reset-filters','','close')}</div>`:''}</div><div class="table-wrap patient-scroll" tabindex="0" role="region" aria-label="Danh sách bệnh nhân, cuộn ngang để xem thêm"><table class="patient-table premium-table ${ui.compact?'compact-density':''}"><thead><tr><th>Người bệnh</th><th>Phòng hiện tại</th><th>Tiến trình khám</th><th>Mức ưu tiên</th><th>Thời gian chờ</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${list.slice((state.pageNumber-1)*10,state.pageNumber*10).map((p,i)=>`<tr data-row-id="${p.id}" class="${p.wait>60&&activeQueue(p)?'needs-attention':''}"><td><button class="patient-name" data-patient="${p.id}" aria-label="Mở hồ sơ ${esc(p.name)}">${avatar(p.name,i)}<span><strong>${esc(p.name)}</strong><small>${p.id} <span>·</span> ${p.age} tuổi <span>·</span> ${p.gender}</small></span></button></td><td><strong>${esc(p.department)}</strong><small>${icon('pin')} ${esc(p.room)}</small></td><td><div class="progress-label"><strong>${p.completed}<span> / 21</span></strong><small>${Math.round(p.completed/21*100)}%</small></div><div class="progress"><span style="width:${p.completed/21*100}%"></span></div></td><td>${badge(p.priority,priorityColor(p.priority))}</td><td><span class="wait-time ${activeQueue(p)&&p.wait>30?'overdue':''}">${icon('clock')} <strong>${p.status==='Hoàn tất'?'—':p.wait}</strong>${p.status==='Hoàn tất'?'':'phút'}</span></td><td>${badge(p.status,statusColor(p.status))}</td><td><div class="actions"><button class="icon-btn" data-patient="${p.id}" title="Xem hồ sơ" aria-label="Xem hồ sơ ${esc(p.name)}">${icon('eye')}</button><button class="icon-btn ai-action" data-patient-ai="${p.id}" title="Gợi ý điều phối" aria-label="Gợi ý cho ${esc(p.name)}">${icon('spark')}</button><button class="icon-btn" data-transfer="${p.id}" title="Chuyển phòng" aria-label="Chuyển phòng cho ${esc(p.name)}">${icon('transfer')}</button></div></td></tr>`).join('')||`<tr><td colspan="7"><div class="empty">${icon('search')}<h3>Chưa tìm thấy người bệnh</h3><p>Thử tên khác hoặc xóa bộ lọc để xem toàn bộ hồ sơ.</p>${button('Xóa bộ lọc','reset-filters','soft','refresh')}</div></td></tr>`}</tbody></table></div><div class="pagination"><span><strong>${list.length?(state.pageNumber-1)*10+1:0}–${Math.min(state.pageNumber*10,list.length)}</strong> trong ${list.length} hồ sơ</span><div class="flex"><button data-page="${Math.max(1,state.pageNumber-1)}" ${state.pageNumber===1?'disabled':''} aria-label="Trang trước">‹</button>${Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" class="${state.pageNumber===i+1?'active':''}" ${state.pageNumber===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}<button data-page="${Math.min(pages,state.pageNumber+1)}" ${state.pageNumber===pages?'disabled':''} aria-label="Trang sau">›</button></div></div></section><div class="patient-hint">${icon('info')} Chọn người bệnh để xem nhanh hồ sơ. Bộ lọc được giữ khi bạn quay lại danh sách.<span><kbd>Esc</kbd> Đóng hồ sơ &nbsp; <kbd>Ctrl K</kbd> Tìm nhanh</span></div>`;};
function restoreDrawerFocus(){const target=ui.drawerFocus;requestAnimationFrame(()=>{if(target?.isConnected)target.focus({preventScroll:true});else $(`[data-patient="${state.patientId}"]`)?.focus({preventScroll:true});});}
function closeDrawer(){ui.drawer=null;$('#drawer-root')?.remove();$('#app').inert=false;document.body.style.overflow='';restoreDrawerFocus();}
function openDrawer(id){if(!state.patients.some(p=>p.id===id))return;ui.drawerFocus=document.activeElement;ui.drawer=id;state.patientId=id;sessionStorage.setItem('opd-patient-id',id);drawDrawer(true);}
function drawDrawer(initial=false){let p=state.patients.find(p=>p.id===ui.drawer);if(!p)return;let root=$('#drawer-root');if(!root){root=document.createElement('div');root.id='drawer-root';document.body.append(root);}const next=activities[Math.min(p.completed,20)];root.innerHTML=`<div class="drawer-backdrop" data-ui="close-drawer"></div><aside class="patient-drawer ${initial?'enter':''}" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><header class="drawer-header"><div><span class="page-kicker">HỒ SƠ NGƯỜI BỆNH</span><span class="muted">${p.id}</span></div><button class="icon-btn" data-ui="close-drawer" aria-label="Đóng hồ sơ" title="Đóng · Esc">${icon('close')}</button></header><div class="drawer-body"><div class="drawer-person">${avatar(p.name)}<div><h2 id="drawer-title">${esc(p.name)}</h2><p>${p.age} tuổi <span>·</span> ${p.gender} <span>·</span> ${esc(p.phone)}</p></div></div><div class="flex drawer-badges">${badge(p.status,statusColor(p.status))}${badge('Ưu tiên '+p.priority.toLowerCase(),priorityColor(p.priority))}</div><div class="drawer-metrics"><div><span>Phòng hiện tại</span><strong>${esc(p.room)}</strong><small>${esc(p.department)}</small></div><div><span>Thời gian chờ</span><strong class="${p.wait>30?'text-red':''}">${p.wait} <small>phút</small></strong><small>${p.wait>30?'Cần xem xét điều phối':'Trong ngưỡng theo dõi'}</small></div></div><section class="drawer-section"><div class="between"><h3>Hành trình khám</h3>${badge(p.completed+'/21 hoạt động','',false)}</div><div class="progress"><span style="width:${p.completed/21*100}%"></span></div><div class="journey-mini">${activities.slice(Math.max(0,p.completed-1),Math.min(21,p.completed+3)).map((a,i)=>{let n=Math.max(0,p.completed-1)+i;return `<div class="journey-step ${n<p.completed?'done':n===p.completed?'current':''}"><span>${n<p.completed?'✓':n+1}</span><div><strong>${a}</strong><small>${n<p.completed?'Đã hoàn thành':n===p.completed?'Hoạt động tiếp theo':'Chưa thực hiện'}</small></div></div>`;}).join('')}</div></section><section class="drawer-suggestion"><div class="flex">${circle('spark','purple')}<div><h3>Hỗ trợ điều phối</h3><p>Kiểm tra gợi ý trước khi chuyển phòng.</p></div></div><button class="link" data-ui="drawer-ai">Xem gợi ý cho người bệnh ${icon('arrow')}</button></section><section class="drawer-section"><div class="between"><h3>Ghi chú chăm sóc</h3><span class="muted">${p.notes.length} ghi chú</span></div><form id="drawer-note-form"><label class="sr-only" for="drawer-note">Nội dung ghi chú</label><textarea id="drawer-note" name="note" required maxlength="500" placeholder="Thông tin cần lưu ý cho bác sĩ, điều phối viên..."></textarea><button type="submit" class="btn soft">${icon('plus')} Lưu ghi chú</button></form><div class="drawer-notes">${p.notes.map(n=>`<div>${avatar('Nguyễn Thị Lan')}<p><strong>Nguyễn Thị Lan <small>${esc(n.time)}</small></strong><span>${esc(n.text)}</span></p></div>`).join('')}</div></section><button class="btn full-width" data-ui="drawer-full">${icon('file')} Mở hồ sơ đầy đủ ${icon('arrow')}</button></div><footer class="drawer-footer"><button class="btn" data-ui="drawer-transfer">${icon('transfer')} Chuyển phòng</button><button class="btn primary" data-ui="drawer-complete" ${p.completed>=21?'disabled':''}>${icon('check')} ${p.completed>=21?'Đã hoàn tất':'Hoàn thành bước'}</button><small>${p.completed>=21?'Người bệnh đã hoàn tất hành trình':esc(next)}</small></footer></aside>`;$('#app').inert=true;document.body.style.overflow='hidden';$('#drawer-note-form').onsubmit=e=>{e.preventDefault();let note=new FormData(e.target).get('note').trim();if(!note)return;p.notes.unshift({text:note,time:new Date().toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Ho_Chi_Minh'})});log('Ghi chú','Thêm ghi chú cho '+p.name,p.id);drawDrawer();$('#drawer-note').focus();toast('Đã lưu ghi chú cho '+p.name);};if(initial)requestAnimationFrame(()=>$('#drawer-root [data-ui="close-drawer"]:is(button)')?.focus());}
function commandPalette(initial=""){modal('Tìm nhanh trong Smart OPD',`<div class="command-search">${icon('search')}<input id="command-input" placeholder="Tìm người bệnh hoặc chức năng..." aria-label="Tìm nhanh" autocomplete="off"><kbd>Esc</kbd></div><div id="command-results"></div><div class="command-footer"><span><kbd>↑</kbd><kbd>↓</kbd> Di chuyển</span><span><kbd>Enter</kbd> Mở kết quả</span></div>`);$('.modal').classList.add('command-modal');function results(){const q=searchText($('#command-input').value);const routes=commandActions.filter(([id,n])=>(id!=='users'||state.role==='Quản trị viên')&&searchText(n).includes(q));const ps=q?state.patients.filter(p=>searchText(p.name+' '+p.id+' '+p.phone).includes(q)).slice(0,6):[];$('#command-results').innerHTML=routes.length?`<div class="command-label">ĐI ĐẾN</div>${routes.map(([id,n,i])=>`<button data-command-route="${id}">${circle(i)}<span>${n}</span>${icon('arrow')}</button>`).join('')}`:'';if(ps.length)$('#command-results').insertAdjacentHTML('beforeend',`<div class="command-label">NGƯỜI BỆNH</div>${ps.map(p=>`<button data-command-patient="${p.id}">${avatar(p.name)}<span>${esc(p.name)}<small>${p.id} · ${p.age} tuổi · ${esc(p.department)}</small></span>${icon('arrow')}</button>`).join('')}`);if(!routes.length&&!ps.length)$('#command-results').innerHTML='<div class="empty">Không tìm thấy kết quả. Thử tên hoặc mã hồ sơ khác.</div>';};$('#command-input').value=initial;results();$('#command-input').oninput=results;setTimeout(()=>$('#command-input')?.focus(),30);}
function preferences(){modal('Tùy chỉnh trải nghiệm',`<div class="modal-body preferences"><p>Thiết lập được lưu cho trình duyệt này.</p><label><span><strong>Giảm chuyển động</strong><small>Tắt hiệu ứng xuất hiện và chuyển cảnh.</small></span><input id="motion-setting" type="checkbox" class="switch" ${motionOff()?'checked':''} ${systemMotion.matches?'disabled':''}></label>${systemMotion.matches?'<p>Đang áp dụng tùy chọn giảm chuyển động của hệ điều hành.</p>':''}<label><span><strong>Bảng dữ liệu gọn</strong><small>Hiển thị nhiều hồ sơ hơn trong cùng màn hình.</small></span><input id="density-setting" type="checkbox" class="switch" ${ui.compact?'checked':''}></label><div class="shortcuts-guide"><h3>Phím tắt</h3><p>Tìm nhanh <kbd>Ctrl / ⌘ + K</kbd></p><p>Tìm trong danh sách bệnh nhân <kbd>/</kbd></p><p>Đóng hồ sơ hoặc hộp thoại <kbd>Esc</kbd></p></div></div>`);$('#motion-setting').onchange=e=>{ui.reduced=e.target.checked;localStorage.setItem('opd-reduced-motion',JSON.stringify(ui.reduced));document.documentElement.classList.toggle('reduce-motion',motionOff());toast('Đã cập nhật tùy chọn chuyển động.');};$('#density-setting').onchange=e=>{ui.compact=e.target.checked;localStorage.setItem('opd-compact',JSON.stringify(ui.compact));render();};}
render=function(){const changed=ui.lastPage!==state.page;const drawerScroll=$('.drawer-body')?.scrollTop;const tableScroll=$('.patient-scroll')?.scrollLeft||0;const y=window.scrollY;baseRender();document.body.dataset.page=state.page;document.documentElement.classList.toggle('reduce-motion',motionOff());$('#app').classList.toggle('page-enter',changed);ui.lastPage=state.page;const profile=$('.avatar.doctor');if(profile)profile.innerHTML='NL';const footer=$('.side-footer');if(footer)footer.innerHTML='<span>SMART OPD <b>2.1</b></span><span>KHOA KHÁM BỆNH</span>';const sb=$('.sidebar-bottom');if(sb&&!$('.sidebar-preferences'))sb.insertAdjacentHTML('afterbegin',`<button class="sidebar-preferences" data-ui="preferences">${icon('settings')} Tùy chỉnh trải nghiệm ${icon('chevron')}</button>`);const topSearch=$('.global-search');if(topSearch){topSearch.onsubmit=e=>{e.preventDefault();commandPalette(topSearch.querySelector('input').value.trim());};topSearch.insertAdjacentHTML('beforeend','<button type="button" class="search-shortcut" data-ui="command" aria-label="Tìm nhanh, Control K"><kbd>Ctrl K</kbd></button>');topSearch.querySelector('input').placeholder='Tìm bệnh nhân, phòng khám, chức năng...';}if($('.top-actions'))$('.top-actions').insertAdjacentHTML('afterbegin',`<span class="top-context">${icon('hospital')} Khoa Khám bệnh</span><button class="icon-btn preference-trigger" data-ui="preferences" title="Tùy chỉnh trải nghiệm" aria-label="Tùy chỉnh trải nghiệm">${icon('settings')}</button>`);$$('button[aria-label]').forEach(b=>{if(!b.title)b.title=b.getAttribute('aria-label');});const overlay=document.createElement('button');overlay.className='mobile-scrim';overlay.dataset.ui='close-menu';overlay.setAttribute('aria-label','Đóng menu');$('.shell')?.prepend(overlay);if(state.page==='patients'){saveFilters();if(!changed){$('.patient-scroll').scrollLeft=tableScroll;window.scrollTo(0,y);}}if(ui.drawer){drawDrawer();if(drawerScroll!==undefined)$('.drawer-body').scrollTop=drawerScroll;}if($('.modal')){ $('#app').inert=true;if($('#drawer-root'))$('#drawer-root').inert=true;} };
modal=function(...args){baseModal(...args);$('#app').inert=true;if($('#drawer-root'))$('#drawer-root').inert=true;};
closeModal=function(){const focus=previousFocus;baseCloseModal();if($('#drawer-root'))$('#drawer-root').inert=false;$('#app').inert=!!ui.drawer;if(ui.drawer)document.body.style.overflow='hidden';requestAnimationFrame(()=>{if(focus?.isConnected)focus.focus({preventScroll:true});});};
function showChangedRow(id){requestAnimationFrame(()=>{let row=$(`[data-row-id="${id}"]`);if(row){row.classList.add('row-updated');setTimeout(()=>row.classList.remove('row-updated'),1600);}});}
document.addEventListener('click',e=>{
 const el=e.target.closest('button,[data-ui]');if(!el)return;
 if(el.dataset.patient){e.preventDefault();e.stopImmediatePropagation();openDrawer(el.dataset.patient);return;}
 if(el.dataset.quick){e.preventDefault();e.stopImmediatePropagation();ui.quick=ui.quick===el.dataset.quick?'':el.dataset.quick;state.pageNumber=1;render();return;}
 if(el.dataset.commandRoute){e.stopImmediatePropagation();closeModal();if(ui.drawer)closeDrawer();navigate(el.dataset.commandRoute);return;}
 if(el.dataset.commandPatient){e.stopImmediatePropagation();const id=el.dataset.commandPatient;closeModal();openDrawer(id);return;}
 if(el.dataset.action==='reset-filters')ui.quick='';
 if(el.dataset.action==='menu'){e.stopImmediatePropagation();$('#sidebar').classList.toggle('open');document.body.classList.toggle('menu-open',$('#sidebar').classList.contains('open'));return;}
 if(navItems.some(x=>x[0]===el.dataset.action)){ui.scroll[state.page]={y:window.scrollY,x:$('.patient-scroll')?.scrollLeft||0};document.body.classList.remove('menu-open');if(ui.drawer)closeDrawer();}
 const act=el.dataset.ui;if(!act)return;e.preventDefault();e.stopImmediatePropagation();
 if(act==='close-drawer')return closeDrawer();
 if(act==='command')return commandPalette();
 if(act==='preferences')return preferences();
 if(act==='close-menu'){document.body.classList.remove('menu-open');$('#sidebar').classList.remove('open');$('.mobile-toggle').focus();return;}
 if(act==='density'){ui.compact=!ui.compact;localStorage.setItem('opd-compact',JSON.stringify(ui.compact));render();$('[data-ui="density"]').focus();return;}
 if(act==='quick-long'){ui.quick='long';state.search='';state.status='Tất cả';state.dept='Tất cả';state.priority='Tất cả';state.pageNumber=1;navigate('patients');return;}
 if(act==='drawer-full'){ui.scroll.patients={y:window.scrollY,x:$('.patient-scroll')?.scrollLeft||0};closeDrawer();navigate('detail');return;}
 if(act==='drawer-ai'){state.aiTarget=ui.drawer;state.aiIndex=Math.max(0,aiPatients().findIndex(p=>p.id===ui.drawer));closeDrawer();navigate('ai');return;}
 if(act==='drawer-transfer'){transfer(ui.drawer);return;}
 if(act==='drawer-complete'){const p=currentPatient();if(p.completed>=21)return;p.completed++;if(p.completed===21){p.status='Hoàn tất';p.wait=0;}log('Cập nhật','Hoàn tất hoạt động '+p.completed+'/21 cho '+p.name,p.id);render();$('#drawer-root [data-ui="drawer-complete"]')?.focus();showChangedRow(p.id);toast('Đã hoàn thành bước '+p.completed+'/21 · '+p.name);}
},true);
document.addEventListener('keydown',e=>{
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();e.stopImmediatePropagation();if($('.command-modal'))closeModal();else commandPalette();return;}
 if(e.key==='/'&&state.page==='patients'&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)&&!ui.drawer&&!$('.modal')){e.preventDefault();$('#patient-search').focus();return;}
 if($('.command-modal')&&['ArrowDown','ArrowUp','Enter'].includes(e.key)){const rows=$$('#command-results button');if(!rows.length)return;let idx=rows.indexOf(document.activeElement);if(e.key==='Enter'){if(document.activeElement===$('#command-input')){e.preventDefault();rows[0].click();}return;}e.preventDefault();idx=e.key==='ArrowDown'?Math.min(rows.length-1,idx+1):Math.max(0,idx-1);rows[idx].focus();return;}
 if(e.key==='Escape'&&!$('.modal')){if(ui.drawer){e.preventDefault();e.stopImmediatePropagation();closeDrawer();return;}document.body.classList.remove('menu-open');}
 if(e.key==='Tab'&&ui.drawer&&!$('.modal')){const items=$$('button,input,textarea,select,a[href]',$('.patient-drawer')).filter(x=>!x.disabled);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
},true);
window.addEventListener('hashchange',()=>{document.body.classList.remove('menu-open');if(ui.drawer)closeDrawer();if(state.page==='patients'&&ui.scroll.patients)requestAnimationFrame(()=>{window.scrollTo(0,ui.scroll.patients.y);if($('.patient-scroll'))$('.patient-scroll').scrollLeft=ui.scroll.patients.x;});});
systemMotion.addEventListener('change',()=>document.documentElement.classList.toggle('reduce-motion',motionOff()));
render();
